func() {
	if len(batch) == 0 {
		inBatch = false
		return
	}

	payload, err := json.Marshal(map[string]string{"type": "terminal", "id": sid, "d": string(batch)})
	batch = batch[:0]
	inBatch = false
	lastFlush = time.Now()
	if err == nil {
		c.sendTerminalPayload(payload)
	}
}

